CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_insert_book`(
	in p_book_name varchar(255),
    in p_isbn varchar(255),
    in p_author_name varchar(255),
    in p_publisher_name varchar(255),
    in p_category_name varchar(255),
    in p_book_img_url varchar(255)
)
BEGIN
    declare v_author_id int default 0;
    declare v_publisher_id int default 0;
    declare v_category_id int default 0;
    
    start transaction;
   
	call sp_get_author_id(v_author_id, p_author_name);
    call sp_get_publisher_id(v_publisher_id, p_publisher_name);
    call sp_get_category_id(v_category_id, p_category_name);
    
    select v_author_id, v_publisher_id, v_category_id;
    
	insert into book_tb
    values (
    default,
    p_book_name,
    v_author_id,
    p_isbn,
    v_publisher_id,
    v_category_id,
    p_book_img_url
    );
    
    commit;
END ;;
