	start transaction;
    
    call sp_get_course_id(v_course_id, p_course_name);
    call sp_get_instructor_id(v_instructor_id, p_instructor_name);
    call sp_get_major_id(v_major_id, p_major_name);
    
    insert into course_registering_information_tb
    values (
