CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_loop_insert_data_b`(
	in count int
)
BEGIN
	declare i int default 0;

	while i < count do 
		insert into data_b_tb
        values(default, concat('2025', i));
        
        set i = i + 1;
    end while;
END ;;
